<?php
require_once __DIR__ . '/config/util.php';
$token=(string)($_GET['token']??'');$key='recuperacao_'.$token;$recovery=$_SESSION[$key]??null;$message='';$done=false;
if(!$recovery||($recovery['expira']??0)<time()){$recovery=null;$message='Link inválido ou expirado.';}
if($recovery&&$_SERVER['REQUEST_METHOD']==='POST'){if(strlen(post('senha'))<6||post('senha')!==post('confirmacao')){$message='As senhas devem ter ao menos 6 caracteres e ser iguais.';}else{$stmt=conecta()->prepare('UPDATE usuario SET senha=:senha WHERE LOWER(email)=LOWER(:email)');$stmt->execute([':senha'=>password_hash(post('senha'),PASSWORD_DEFAULT),':email'=>$recovery['email']]);unset($_SESSION[$key]);$done=true;$message='Senha alterada com sucesso.';}}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Redefinir senha</title><link rel="stylesheet" href="/assets/css/global.css"><link rel="stylesheet" href="/assets/css/admin.css"></head><body><main class="admin-page"><div class="admin-card"><h1>Redefinir senha</h1><p class="admin-message <?=($done||$recovery)?'':'admin-error'?>"><?=e($message)?></p><?php if($recovery&&!$done):?><form class="admin-form" method="post"><label>Nova senha<input type="password" name="senha" minlength="6" required></label><label>Confirme a senha<input type="password" name="confirmacao" minlength="6" required></label><button class="admin-button">Alterar senha</button></form><?php endif;?></div></main></body></html>
